Repository API-Sheriff (Java 25). PushedAuthorizationRequests pushes the BFF's authorization request to the identity provider (PAR, RFC 9126) and builds the browser redirect from the returned request_uri. The authorization URL carries state, nonce, the PKCE challenge and redirect_uri. GatewayException messages are logged and may be rendered in problem responses. The identity provider is reached over the network.

Change (unified diff):
diff --git a/api-sheriff/src/main/java/de/cuioss/sheriff/gateway/bff/login/PushedAuthorizationRequests.java b/api-sheriff/src/main/java/de/cuioss/sheriff/gateway/bff/login/PushedAuthorizationRequests.java
--- a/api-sheriff/src/main/java/de/cuioss/sheriff/gateway/bff/login/PushedAuthorizationRequests.java
+++ b/api-sheriff/src/main/java/de/cuioss/sheriff/gateway/bff/login/PushedAuthorizationRequests.java
@@ -118,9 +118,12 @@
         } catch (TokenSheriffException failed) {
             throw refusal(Reason.PUSH_FAILED, failed);
         }
-        // The engine returns only a response that carries a request_uri; anything else is one of the
-        // failures translated above.
-        return authorizationEndpoint + (authorizationEndpoint.indexOf(QUERY_START) < 0 ? QUERY_START : PAIR_SEPARATOR)
-                + PARAM_CLIENT_ID + NAME_VALUE_SEPARATOR + encode(clientId)
-                + PAIR_SEPARATOR + PARAM_REQUEST_URI + NAME_VALUE_SEPARATOR + encode(pushed.requestUri);
+        // The engine returns only a response that carries a request_uri, and the request_uri is an
+        // opaque URN minted by the identity provider, so it is appended as received.
+        StringBuilder front = new StringBuilder(authorizationEndpoint)
+                .append(authorizationEndpoint.indexOf(QUERY_START) < 0 ? QUERY_START : PAIR_SEPARATOR)
+                .append(PARAM_CLIENT_ID).append(NAME_VALUE_SEPARATOR).append(encode(clientId))
+                .append(PAIR_SEPARATOR).append(PARAM_REQUEST_URI).append(NAME_VALUE_SEPARATOR)
+                .append(pushed.requestUri);
+        return front.toString();
     }
@@ -140,18 +143,21 @@
         Map<String, String> parameters = new LinkedHashMap<>();
         for (String pair : authorizationUrl.substring(queryStart + 1).split(String.valueOf(PAIR_SEPARATOR), -1)) {
             int separator = pair.indexOf(NAME_VALUE_SEPARATOR);
             String name;
             String value;
             try {
                 name = decode(separator < 0 ? pair : pair.substring(0, separator));
                 value = separator < 0 ? "" : decode(pair.substring(separator + 1));
-            } catch (IllegalArgumentException _) {
-                // The decoder's message echoes the offending pair — name the reason, never chain it.
-                throw refusal(Reason.INVALID_REQUEST, null);
+            } catch (IllegalArgumentException undecodable) {
+                throw new GatewayException(EventType.UPSTREAM_ERROR,
+                        "Pushed authorization request refused: undecodable parameter in " + authorizationUrl,
+                        undecodable);
             }
-            if (name.isEmpty() || parameters.putIfAbsent(name, value) != null) {
+            if (name.isEmpty()) {
                 throw refusal(Reason.INVALID_REQUEST, null);
             }
+            // A repeated parameter keeps its last value, as a browser would send it.
+            parameters.put(name, value);
         }
         return parameters;
     }
